package com.timetune.repository;
import com.timetune.domain.Song;import org.springframework.stereotype.Repository;import java.util.List;import java.util.Optional;
@Repository public class SongCatalog {private final SongRepository repo;public SongCatalog(SongRepository r){repo=r;}public List<Song> all(){return repo.findAll();}public Optional<Song> findById(String id){return repo.findByCatalogueId(id);}}